//###########################################################
sortColumn = "profitAvg";

sortAscending = false;

numRows = 50;

//###########################################################
selectedEl = null;

selectedResult = null;

//###########################################################
export var screenAndRender = async function(chosenEvents, symbolToData) {
  var err, results;
  log("screenAndRender");
  log("chosenEvents.length: " + chosenEvents.length);
  olog(chosenEvents.map(function(el) {
    return el.id;
  }));
  log("Object.keys(symbolToData).length: " + Object.keys(symbolToData).length);
  if (chosenEvents.length > 0 && Object.keys(symbolToData).length > 0) {
    setUIState("processing");
    try {
      await screener.startScreening(symbolToData, chosenEvents);
      results = screener.getResults(numRows, sortColumn, sortAscending);
      render(results);
      setUIState("result");
      return;
    } catch (error) {
      err = error;
      setUIState("no-result");
      console.error(err);
    }
  } else {
    setUIState("no-result");
  }
};

//###########################################################
render = function(results) {
  var d, dataStructure, headerRow, i, j, k, key, label, len, len1, len2, result, row, sort, tbody, td, th, thead;
  log("render");
  if (!Array.isArray(results)) {
    throw new Error("Results is not an Array!");
  }
  if (results.length === 0) {
    throw new Error("Results is empty Array!");
  }
  eventscreenerResult.innerHTML = "";
  dataStructure = screener.resultStructure;
  //#######################################################
  // render table head
  thead = document.createElement("thead");
  headerRow = document.createElement("tr");
  for (i = 0, len = dataStructure.length; i < len; i++) {
    ({label, key, sort} = dataStructure[i]);
    th = document.createElement("th");
    if (key != null) {
      th.dataset.key = key;
      if (sort !== "none") {
        th.classList.add("sortable");
      }
      if (key === sortColumn) {
        th.classList.add("sorted");
        th.classList.add(sortAscending ? "asc" : "desc");
      }
      th.addEventListener("click", onSortColumnClick);
    }
    th.innerHTML = label;
    headerRow.appendChild(th);
  }
  thead.appendChild(headerRow);
  eventscreenerResult.appendChild(thead);
  
  //#######################################################
  // render table body
  tbody = document.createElement("tbody");
  for (j = 0, len1 = results.length; j < len1; j++) {
    result = results[j];
    row = document.createElement("tr");
    if ((selectedResult != null) && (selectedResult.groupKey != null) && result.groupKey === selectedResult.groupKey) {
      log(`selecting row with groupKey: ${result.groupKey} as selectedGroupKey is: ${selectedResult.groupKey}`);
      selectedEl = row;
      selectedResult = result;
      selectedEl.classList.add("chosen");
    }
    let lettedResult = result;
    row.addEventListener("click", function() {
      return selectForDetailsView(this, lettedResult);
    });
    for (k = 0, len2 = dataStructure.length; k < len2; k++) {
      ({label, key, sort} = dataStructure[k]);
      td = document.createElement("td");
      d = result[key];
      switch (key) {
        case "symbol":
          td.appendChild(getSpan("symbol", d));
          break;
        // when "eventLabel" then td.appendChild(getSpan("", d+"\n"+result.tradeKey))
        case "eventLabel":
          td.appendChild(getSpan("", d));
          break;
        case "direction":
          td.appendChild(getSpan(d.toLowerCase(), d));
          break;
        case "winrate":
          td.appendChild(getSpan("winrate", d.toFixed(1)));
          break;
        case "profitAvg":
          td.appendChild(getSpan("profit", d.toFixed(1)));
          break;
        case "profitMed":
          td.appendChild(getSpan("profit", d.toFixed(1)));
          break;
        case "maxRise":
          td.appendChild(getMaxRiseElement(result));
          break;
        case "maxDrop":
          td.appendChild(getMaxDropElement(result));
          break;
        case "nextDate":
          td.appendChild(getSpan("", formatDate(d)));
          break;
        case "entryDate":
          td.appendChild(getSpan("", formatDate(d)));
          break;
        case "exitDate":
          td.appendChild(getSpan("", formatDate(d)));
          break;
        default:
          console.error(`Rendering TableBody: Unexpected key ${key}!`);
      }
      row.appendChild(td);
    }
    tbody.appendChild(row);
  }
  eventscreenerResult.appendChild(tbody);
};

//###########################################################
selectForDetailsView = function(el, result) {
  log("selectForDetailsView");
  if (selectedEl != null) {
    selectedEl.classList.remove("chosen");
  }
  selectedEl = el;
  selectedResult = result;
  el.classList.add("chosen");
  displayDetails(result);
  setUIState("details");
  eventscreenerframe.scrollTo({
    top: 0,
    behavior: 'smooth'
  });
};

//###########################################################
//region helper functions for table rendering
onSortColumnClick = function(evnt) {
  var key, results;
  key = evnt.target.getAttribute("data-key");
  log(`onSortColumnClick: ${key}`);
  if (sortColumn === key) {
    sortAscending = !sortAscending; // Toggle direction
// switch sort column
  } else {
    sortColumn = key;
    sortAscending = false; // New column: start descending
  }
  results = screener.getResults(numRows, sortColumn, sortAscending);
  render(results);
};

//###########################################################
formatPercent = function(value) {
  var sign;
  sign = value >= 0 ? "+" : "";
  return `${sign}${value.toFixed(1)}%`;
};

formatDate = function(value) {
  var date, day, dayStr, month, monthStr, year;
  date = new Date(value);
  day = date.getDate();
  month = date.getMonth() + 1;
  year = date.getFullYear();
  dayStr = day < 10 ? `0${day}` : `${day}`;
  monthStr = month < 10 ? `0${month}` : `${month}`;
  return `${dayStr}.${monthStr}.${year}`;
};

formatAbsolutePrice = function(value, missingSF) {
  if (missingSF > 1) {
    return `${value.toFixed(2)}<span class='missing-factor' title='Fehlender Faktor zum exakten historischen Wert.'>${missingSF.toFixed(2)}</span>`;
  } else {
    return `${value.toFixed(2)}`;
  }
};

//###########################################################
getSpan = function(cls, txt) {
  var span;
  span = document.createElement("SPAN");
  span.className = cls;
  span.textContent = txt;
  return span;
};

getMaxRiseElement = function(result) {
  var abs, absEl, bottom, el, missingSF, p, top;
  log("getMaxRiseElement");
  olog(result);
  abs = result.maxRiseAba;
  p = result.maxRise;
  missingSF = result.maxRiseMissingSF;
  olog({p, abs, missingSF});
  el = document.createElement("div");
  top = document.createElement("div");
  bottom = document.createElement("div");
  absEl = document.createElement("span");
  bottom.classList.add("absolute");
  absEl.classList.add("abs-up");
  el.appendChild(top);
  el.appendChild(bottom);
  top.appendChild(getSpan("up", p.toFixed(1)));
  absEl.innerHTML = formatAbsolutePrice(abs, missingSF);
  bottom.appendChild(absEl);
  return el;
};

